package io.github.polestarcn.companion;
import android.content.Context;import android.text.*;import android.view.View;import android.widget.*;import java.util.*;
/** Search indexes real settings actions, including collapsed groups, without changing their saved state. */
final class SettingsSearch {
 static final class Item {final String label,terms;final Runnable action;Item(String l,String t,Runnable a){label=l;terms=(l+" "+t).toLowerCase(Locale.ROOT);action=a;}}
 final List<Item> items=new ArrayList<>();private final Context c;private final LinearLayout results;private View groups;String query="";
 SettingsSearch(Context c,LinearLayout root){this.c=c;EditText input=new EditText(c);input.setTag("settings_search");input.setSingleLine(true);input.setTextColor(PsaDesign.ink(AppPreferences.dark(c)));input.setHintTextColor(PsaDesign.muted(AppPreferences.dark(c)));input.setHint(AppPreferences.tr(c,"搜索设置（如：字体、吸入、备份）","Search settings (font, particles, backup)"));input.setTextSize(15);root.addView(input,new LinearLayout.LayoutParams(-1,Math.round(52*c.getResources().getDisplayMetrics().density)));results=new LinearLayout(c);results.setOrientation(LinearLayout.VERTICAL);results.setTag("settings_search_results");root.addView(results);input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString();filter();}public void afterTextChanged(Editable e){}});}
 void add(String label,String terms,Runnable action){items.add(new Item(label,terms,action));}
 void attach(View groups){this.groups=groups;filter();}
 List<Item> matches(String query){List<Item> out=new ArrayList<>();String[] words=query.trim().toLowerCase(Locale.ROOT).split("\\s+");for(Item i:items){boolean match=true;for(String word:words)if(!i.terms.contains(word))match=false;if(match)out.add(i);}return out;}
 private void filter(){if(groups==null)return;boolean search=!query.trim().isEmpty();groups.setVisibility(search?View.GONE:View.VISIBLE);results.setVisibility(search?View.VISIBLE:View.GONE);results.removeAllViews();if(!search)return;List<Item> found=matches(query);if(found.isEmpty()){TextView empty=new TextView(c);empty.setText(AppPreferences.tr(c,"没有匹配的设置","No matching settings"));empty.setTextColor(PsaDesign.muted(AppPreferences.dark(c)));results.addView(empty);}for(Item item:found){Button b=new Button(c);b.setText(item.label);b.setTextColor(PsaDesign.ink(AppPreferences.dark(c)));b.setAllCaps(false);b.setOnClickListener(v->{Haptics.tap(c);item.action.run();});results.addView(b);}UiTypography.applyTree(results);}
}
